export const envelope = [31, 30, 15];

export default function build(api) {
  const oakPlanks = "minecraft:oak_planks";
  const sprucePlanks = "minecraft:spruce_planks";
  const darkPlanks = "minecraft:dark_oak_planks";

  const oakX = "minecraft:oak_log[axis=x]";
  const oakZ = "minecraft:oak_log[axis=z]";
  const spruceZ = "minecraft:spruce_log[axis=z]";
  const darkX = "minecraft:dark_oak_log[axis=x]";
  const darkY = "minecraft:dark_oak_log[axis=y]";

  const blackWool = "minecraft:black_wool";
  const coalBlock = "minecraft:coal_block";
  const ladder = "minecraft:ladder[facing=south]";
  const closedHatch =
    "minecraft:dark_oak_trapdoor[facing=south,half=top,open=false,powered=false,waterlogged=false]";

  function put(x, y, z, block) {
    api.set(x, y, z, block);
  }

  function box(x0, x1, y0, y1, z0, z1, block) {
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        for (let z = z0; z <= z1; z++) {
          put(x, y, z, block);
        }
      }
    }
  }

  function groundY(x, z) {
    let h = Math.floor(api.heightAt(x, z));
    if (h < 0) {
      h = 0;
    }
    return h;
  }

  const bodyLayers = [
    [4, 9, 19, 4, 10],
    [5, 7, 21, 3, 11],
    [6, 6, 22, 2, 12],
    [7, 6, 22, 2, 12],
    [8, 6, 22, 2, 12],
    [9, 6, 22, 2, 12],
    [10, 6, 22, 2, 12],
    [11, 6, 22, 2, 12],
    [12, 6, 22, 2, 12],
    [13, 6, 22, 2, 12],
    [14, 7, 21, 3, 11],
    [15, 9, 20, 4, 10]
  ];

  for (let i = 0; i < bodyLayers.length; i++) {
    const layer = bodyLayers[i];
    const y = layer[0];
    const x0 = layer[1];
    const x1 = layer[2];
    const z0 = layer[3];
    const z1 = layer[4];

    for (let x = x0; x <= x1; x++) {
      for (let z = z0; z <= z1; z++) {
        if (
          y >= 5 &&
          y <= 10 &&
          x >= 9 &&
          x <= 19 &&
          z >= 5 &&
          z <= 9
        ) {
          continue;
        }

        let block =
          (x * 3 + y * 5 + z * 7) % 11 === 0
            ? sprucePlanks
            : oakPlanks;

        if (y === 4 || y === 11) {
          block = (x + z) % 3 === 0 ? spruceZ : oakZ;
        } else if (
          (z === 3 || z === 11) &&
          (y === 5 || y === 8 || y === 13)
        ) {
          block = darkX;
        } else if (
          (z === 2 || z === 12) &&
          (y === 6 || y === 9 || y === 12)
        ) {
          block = oakX;
        } else if (
          (x === 7 || x === 21) &&
          (z === 3 || z === 11) &&
          y >= 5 &&
          y <= 13
        ) {
          block = darkY;
        }

        put(x, y, z, block);
      }
    }
  }

  const legs = [
    [8, 9, 3, 4],
    [8, 9, 10, 11],
    [19, 20, 3, 4],
    [19, 20, 10, 11]
  ];

  for (let i = 0; i < legs.length; i++) {
    const leg = legs[i];

    for (let x = leg[0]; x <= leg[1]; x++) {
      for (let z = leg[2]; z <= leg[3]; z++) {
        let start = groundY(x, z);

        if (start > 5) {
          start = 5;
        }

        for (let y = start; y <= 5; y++) {
          put(x, y, z, y === start ? darkPlanks : darkY);
        }
      }
    }
  }

  for (const y of [6, 9, 12]) {
    for (let x = 6; x <= 22; x++) {
      put(x, y, 2, oakX);
      put(x, y, 12, oakX);
    }
  }

  for (const y of [5, 8, 13]) {
    for (let x = 7; x <= 21; x++) {
      put(x, y, 3, darkX);
      put(x, y, 11, darkX);
    }
  }

  for (const x of [8, 20]) {
    for (let y = 5; y <= 13; y++) {
      put(x, y, 2, darkY);
      put(x, y, 12, darkY);
    }
  }

  for (const x of [7, 21]) {
    for (let z = 2; z <= 12; z++) {
      put(x, 11, z, oakZ);
    }
  }

  const pegs = [
    [8, 6, 3],
    [20, 6, 11],
    [8, 9, 3],
    [20, 9, 11],
    [7, 13, 3],
    [21, 8, 11]
  ];

  for (let i = 0; i < pegs.length; i++) {
    put(pegs[i][0], pegs[i][1], pegs[i][2], darkPlanks);
  }

  box(5, 8, 10, 13, 5, 9, darkPlanks);
  box(3, 6, 8, 12, 5, 9, sprucePlanks);
  box(1, 4, 6, 10, 4, 10, darkPlanks);
  box(0, 2, 5, 8, 3, 11, darkPlanks);

  for (let x = 5; x <= 7; x++) {
    put(x, 12, 7, darkX);
  }

  for (let x = 3; x <= 5; x++) {
    put(x, 10, 7, darkX);
  }

  for (let x = 1; x <= 3; x++) {
    put(x, 8, 7, darkX);
  }

  for (let x = 0; x <= 1; x++) {
    put(x, 6, 7, darkX);
  }

  box(20, 22, 11, 14, 3, 11, sprucePlanks);

  for (let y = 11; y <= 14; y++) {
    put(21, y, 3, darkY);
    put(21, y, 11, darkY);
  }

  const neckLayers = [
    [12, 19, 23, 4, 10],
    [13, 19, 23, 4, 10],
    [14, 20, 24, 4, 10],
    [15, 20, 24, 5, 9],
    [16, 21, 25, 5, 9],
    [17, 21, 25, 5, 9],
    [18, 22, 26, 5, 9],
    [19, 22, 26, 5, 9],
    [20, 23, 27, 5, 9],
    [21, 23, 27, 5, 9],
    [22, 24, 28, 5, 9],
    [23, 24, 28, 5, 9]
  ];

  for (let i = 0; i < neckLayers.length; i++) {
    const layer = neckLayers[i];
    const y = layer[0];

    for (let x = layer[1]; x <= layer[2]; x++) {
      for (let z = layer[3]; z <= layer[4]; z++) {
        let block =
          (x + y * 2 + z) % 6 === 0 ? sprucePlanks : oakPlanks;

        if (z === layer[3] && y % 2 === 0) {
          block = darkPlanks;
        }

        put(x, y, z, block);
      }
    }
  }

  for (let y = 14; y <= 23; y++) {
    const west = neckLayers[y - 12][1];

    put(west - 1, y, 4, darkY);
    put(west - 1, y, 5, darkPlanks);

    if (y >= 16 && y % 2 === 0) {
      put(west - 2, y, 5, darkPlanks);
      put(west - 2, y, 6, darkPlanks);
    }
  }

  const headLayers = [
    [21, 26, 30, 5, 9],
    [22, 24, 30, 4, 10],
    [23, 24, 29, 3, 10],
    [24, 24, 29, 3, 10],
    [25, 25, 28, 4, 9],
    [26, 26, 28, 4, 9]
  ];

  for (let i = 0; i < headLayers.length; i++) {
    const layer = headLayers[i];

    box(
      layer[1],
      layer[2],
      layer[0],
      layer[0],
      layer[3],
      layer[4],
      layer[0] <= 22 ? sprucePlanks : oakPlanks
    );
  }

  box(27, 30, 20, 21, 5, 9, darkPlanks);
  box(29, 30, 21, 23, 5, 9, darkPlanks);

  put(30, 22, 6, coalBlock);
  put(30, 22, 8, coalBlock);

  put(27, 24, 2, blackWool);
  put(27, 24, 11, blackWool);

  box(25, 26, 26, 28, 4, 5, darkY);
  box(25, 26, 26, 28, 9, 10, darkY);

  put(26, 29, 5, darkPlanks);
  put(26, 29, 9, darkPlanks);

  const ladderBottom = Math.max(groundY(19, 4), groundY(19, 5));

  for (let y = ladderBottom; y < 4; y++) {
    put(19, y, 5, ladder);
  }

  put(19, 4, 5, closedHatch);
  put(18, 4, 5, darkPlanks);
  put(19, 4, 4, darkPlanks);
  put(19, 4, 6, darkPlanks);

  return {
    name: "The Trojan Horse of Troy",
    seatY: 0,
    anchors: {
      door: [19, 0, 6],
      hatch: [19, 4, 5]
    },
    interiors: [
      {
        min: [9, 5, 5],
        max: [19, 10, 9],
        kind: "quarters"
      }
    ]
  };
}
